const $=id=>document.getElementById(id);let busy=false;
const next=new URLSearchParams(location.search).get('return_to')||'/testing-workbench.html';
function target(){try{const u=new URL(next,location.origin);return u.origin===location.origin&&!u.pathname.startsWith('/api/')?u.pathname+u.search+u.hash:'/testing-workbench.html';}catch{return '/testing-workbench.html';}}
async function send(action){if(busy)return;if(!$('account-form').reportValidity())return;busy=true;$('signin').disabled=$('signup').disabled=true;try{const r=await fetch('/api/auth/'+action,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({email:$('email').value,password:$('password').value})});const d=await r.json();$('status').textContent=d.message||d.error||'Unable to sign in.';if(r.ok&&d.signedIn)location.assign(target());}catch{$('status').textContent='Connection unavailable. Try again.';}finally{busy=false;$('signin').disabled=$('signup').disabled=false;$('password').value='';}}
$('account-form').onsubmit=e=>{e.preventDefault();send('signin');};$('signup').onclick=()=>send('signup');
$('signout').onclick=async()=>{try{const r=await fetch('/api/auth/signout',{method:'POST'});if(!r.ok)throw Error();location.reload();}catch{$('status').textContent='Could not sign out. Please retry.';}};
fetch('/api/auth/session').then(r=>r.json()).then(d=>{if(d.signedIn){$('status').textContent='Signed in as '+d.email;$('signout').hidden=false;const a=document.createElement('a');a.href=target();a.textContent='Continue to workspace →';$('status').append(document.createElement('br'),a);}else if(d.error)$('status').textContent=d.error;}).catch(()=>{$('status').textContent='Sign-in service is unavailable.';});
